def verifier_ip(s: str) -> bool:
    """Renvoie True si `s` est une adresse IPv4 valide, sinon False."""
    parts = s.split('.')
    if len(parts) != 4:
        return False

    for part in parts:
        # Vérifier que le segment est numérique
        if not part.isdigit():
            return False

        # Éviter les zéros initiaux (sauf le cas de "0")
        if len(part) > 1 and part[0] == '0':
            return False

        # Vérifier la plage 0‑255
        num = int(part)
        if num < 0 or num > 255:
            return False

    return True
```

