def dichotomie(l, x):
    """Binary search for x in sorted list l.
    Returns the index of x if found, otherwise -1."""
    left, right = 0, len(l) - 1
    while left <= right:
        mid = (left + right) // 2
        if l[mid] == x:
            return mid
        elif l[mid] < x:
            left = mid + 1
        else:
            right = mid - 1
    return -1
```

